\label{lem:mixed-terminal}
Suppose $P^{1/100}\leqslant L\leqslant P^{d/2}$ and $\alpha\in\mathfrak n(L)$.  Then
\begin{equation*}                          
 \sum_{ 1 \leqslant  x \leqslant P }\sum_{ 1 \leqslant  y \leqslant P}
 \omega_1 \left( \frac{x}{P} \right) \omega_2 \left( \frac{y}{P} \right) \Lambda(x) \, \Lambda(y) \, e\bigl(\Phi(x,y)\bigr)
 \ll P^{2 + \varepsilon} L^{- \frac{1}{d(d-1)(d-2)} },
\end{equation*}
for any $\varepsilon > 0$. Here the implicit constant is independent of the coefficients of $\Phi(x, y) - c \alpha x^{d-1}y$.

\cite[Proposition~5.1]{liuzhao}
\label{LZ}
Let $S(\alpha)$ be as in \eqref{defS} and $f, g$ as in \eqref{deffg}.
Let $X \leqslant \frac14 P^{ \frac{d}{2} }$. Let $\kappa_1$ and $\kappa_2$ be real numbers such that
$$
\min (\kappa_1, \kappa_2)  > (d-1) 2^d.
$$
Suppose
$$
m - \dim V_f^*  \geqslant \kappa_1 \qquad
\textnormal{and}
\qquad
m + s - \dim V_g^*  \geqslant \kappa_2.
$$
Let $\mathfrak{a} \subseteq \mathbb{R} / \mathbb{Z}$ be a measurable set.
Then we have
\begin{eqnarray*}

\int_{\mathfrak{a}} S(\alpha) \mathrm{d} \alpha  &\ll&  P^{n - \frac{d}{2}}   (\log P)^{2n}  X^{1 - \frac{   \kappa_1 }{ (d-1) 2^d  } }  |\mathfrak{a}|^{\frac12}
\\
&&+ P^{ n - \frac{3d}{4} }   (\log P)^{2n}  X^{\frac{3}{2} - \frac{   \kappa_2 }{ (d-1) 2^{d+1}  } }  |\mathfrak{a}|^{\frac14}
\\
&&+ P^{ m + s - d }   (\log P)^{m + s}  X^{2} \sup_{\alpha \in \mathfrak{a}} \sup_{ (\mathbf{y}, \mathbf{z}) \in  [0, P]^{m + s} \cap \mathbb{Z}^{m + s}  } |  \mathcal{E}_{\mathbf{y}, \mathbf{z}} (\alpha) |.
\end{eqnarray*}
